        <x-cms.card title="Activation History" subtitle="Latest 10 pairing attempts; codes are never recoverable."><ul class="space-y-2 text-xs text-gray-600">@forelse($pairings as $pair)<li class="rounded border p-2">Created {{ $pair->created_at->setTimezone($timezone)->format('Y-m-d H:i T') }} / {{ $pair->consumed_at ? 'Consumed' : ($pair->cancelled_at ? 'Dibatalkan' : ($pair->expires_at->isPast() ? 'Expired' : 'Pending')) }}<br>Expires {{ $pair->expires_at->setTimezone($timezone)->format('Y-m-d H:i:s T') }} / Attempts {{ $pair->attempts }}</li>@empty<li>No activation history.</li>@endforelse</ul></x-cms.card>
